try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  const ai = JSON.parse(cleaned);
  const merged = { ...orig, ...ai };

  // Pre-filled category rule: if BOTH were in the sheet already, keep them
  if (orig.profession_name && orig.profession_name.trim() !== '' &&
      orig.services && orig.services.trim() !== '') {
    merged.profession_name = orig.profession_name;
    merged.services = orig.services;
  }

  // Validate profession_name
  if (merged.profession_name && !VALID_PROFESSIONS.includes(merged.profession_name.trim())) {
    return [{ json: { 
      ...orig, 
      status: 'ai_error', 
      notes: `Invalid profession_name: "${merged.profession_name}"` 
    }}];
  }

  // Validate each services entry
  if (merged.services) {
    const serviceList = merged.services.split(',').map(s => s.trim()).filter(Boolean);
    const invalidServices = serviceList.filter(s => !VALID_SERVICES.includes(s));
    if (invalidServices.length > 0) {
      return [{ json: { 
        ...orig, 
        status: 'ai_error', 
        notes: `Invalid services: ${invalidServices.join(' | ')}`.slice(0, 500)
      }}];
    }
  }

  // Compute website_canonical if missing
  if (!merged.website_canonical && merged.website) {
    merged.website_canonical = merged.website
      .toLowerCase()
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .replace(/\/$/, '');
  }

  // Placeholder email
  const canonicalClean = (merged.website_canonical || orig.website_canonical || '')
    .replace(/^https?:\/\//, '');
  merged.email = canonicalClean + '@webpointx.com';
  // Placeholder password
  merged.password = 'W3bP0intXTemp!';

  delete merged.published;
  delete merged.verified;
  delete merged.source;
  delete merged.logo;

  merged.status = 'ai_complete';
  return [{ json: merged }];

} catch(e) {
  return [{ json: { 
    ...orig, 
    status: 'ai_error', 
    notes: ('Parse error: ' + raw).slice(0, 500)
  }}];
}

const items = $input.all();
const newCount = items.filter(i => i.json.status === 'ai_complete').length;
const errorCount = items.filter(i => i.json.status === 'ai_error').length;
const dupCount = items.filter(i => i.json.status === 'duplicate_archived').length;
const knownCount = newCount + errorCount + dupCount;
const totalCount = items.length;
const droppedCount = totalCount - knownCount;

return [{ json: {
  newCount,
  errorCount,
  dupCount,
  droppedCount,
  totalCount,
  batchLabel: $('Compute Batch Label1').item.json.batchLabel,
  batchId: $('Store Batch ID1').item.json.batchId
}}];
